PROGRAM ST550_STRACKFILM
VAR
    steg        : INT := 0;
    tmrVarv     : TON;
    trigReset   : R_TRIG;
    nForraVarv  : INT := 0;
    xVarvRor    : BOOL := FALSE;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDrift      : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. Den har logiken ror inte
   sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* --- larmkallorna samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter de don den ska stoppa. --- *)

(* Pulsgivarvakt. Vid 12 varv/min tar ett varv 5,0 s, sa vakten maste rymma
   ett helt varv. Rors inte raknaren pa 8,0 s medan bordet ar kommenderat
   runt har givaren tappats eller sa star bordet still under filmvagnen -
   och da lagger vagnen filmen pa ett och samma stalle tills den river. *)
IF ST550_TBL_REV <> nForraVarv THEN
    nForraVarv := ST550_TBL_REV;
    xVarvRor := TRUE;
ELSE
    xVarvRor := FALSE;
END_IF;
tmrVarv(IN := ST550_TBL_RUN AND NOT xVarvRor, PT := T#8s);
IF tmrVarv.Q THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET och att nodstopp och
   tryckluft ar tillbaka. Larmet slapper aldrig av sig sjalvt. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDrift := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDrift THEN
    ST550_TBL_RUN := FALSE;
    ST550_FLM_UP := FALSE;
    ST550_FLM_DOWN := FALSE;
    ST550_FLM_CUT := FALSE;
    ST550_LBL_APPLY := FALSE;
    ST550_CNV_RUN := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            (* pallen star pa vridbordet, vagnen nere och bordet i hemlage *)
            IF ST550_PEC_PAL AND ST550_FLM_BOT AND ST550_TBL_HOME THEN
                ST550_TBL_RUN := TRUE;
                steg := 1;
            END_IF;
        1:
            (* tre lasvarv i botten innan svepet borjar *)
            IF ST550_TBL_REV >= 3 THEN
                ST550_FLM_UP := TRUE;
                steg := 2;
            END_IF;
        2:
            (* sju varv uppat, 250 mm stigning per varv *)
            IF ST550_FLM_TOP THEN
                ST550_FLM_UP := FALSE;
                steg := 3;
            END_IF;
        3:
            (* tva varv i topp innan vagnen vander *)
            IF ST550_TBL_REV >= 12 THEN
                ST550_FLM_DOWN := TRUE;
                steg := 4;
            END_IF;
        4:
            (* sju varv nedat *)
            IF ST550_FLM_BOT THEN
                ST550_FLM_DOWN := FALSE;
                steg := 5;
            END_IF;
        5:
            (* nitton varv lagda: stanna bordet och lat det ga till hemlage *)
            IF ST550_TBL_REV >= 19 THEN
                ST550_TBL_RUN := FALSE;
                steg := 6;
            END_IF;
        6:
            (* klipp och svetsa filmen forst nar bordet star i hemlage, annars
               klipps filmen mitt pa lasten *)
            IF ST550_TBL_HOME THEN
                ST550_FLM_CUT := TRUE;
                steg := 7;
            END_IF;
        7:
            ST550_LBL_APPLY := TRUE;
            IF ST550_LBL_APPLIED THEN
                ST550_LBL_APPLY := FALSE;
                ST550_CNV_RUN := TRUE;
                steg := 8;
            END_IF;
        8:
            IF NOT ST550_PEC_PAL THEN
                ST550_CNV_RUN := FALSE;
                ST550_FLM_CUT := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

